import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class DelegatingMethod_equals_TriageGen1Test {



    @Test
    public void testEquals_withNull() throws NoSuchMethodException {
        Method method = String.class.getMethod("length");
        DelegatingMethod delegatingMethod = new DelegatingMethod(method);

        // method.equals(null) returns false in standard java.lang.reflect.Method
        assertFalse(delegatingMethod.equals(null));
    }




}

package org.mockito.internal.creation;

import java.io.*;
import java.lang.reflect.Method;
import java.lang.reflect.Modifier;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import org.mockito.internal.invocation.MockitoMethod;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class DelegatingMethod_equals_TriageGen1Test {





    @Test
    public void testEquals_withMatchingMethodObject() throws NoSuchMethodException {
        Method method = String.class.getMethod("length");
        DelegatingMethod delegatingMethod = new DelegatingMethod(method);

        // To make method.equals(o) return true, 'o' must be the Method object itself.
        // Note: The implementation delegates to 'method.equals(o)', not 'this.equals(o)'.
        assertTrue(delegatingMethod.equals(method));
    }


}

package org.mockito.internal.creation;

import java.io.*;
import java.lang.reflect.Method;
import java.lang.reflect.Modifier;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import org.mockito.internal.invocation.MockitoMethod;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class DelegatingMethod_equals_TriageGen1Test {







    @Test
    public void testEquals_withDifferentMethodObject() throws NoSuchMethodException {
        Method method1 = String.class.getMethod("length");
        Method method2 = String.class.getMethod("isEmpty");
        DelegatingMethod delegatingMethod = new DelegatingMethod(method1);

        assertFalse(delegatingMethod.equals(method2));
    }
}
